INSERT INTO risk_rule (code, factor, metric, comparator, threshold, level, name, precaution) VALUES
('RAIN_C','rain','precip_total_mm','>=',2,'caution','Rain expected during the hike','Pack a waterproof jacket; rocks and trails may be slippery.'),
('RAIN_W','rain','precip_total_mm','>=',10,'warning','Heavy rain during the hike','Postpone or choose a short, low trail with an easy way out.'),
('WIND_C','wind','gust_max_kmh','>=',40,'caution','Strong wind gusts','Avoid exposed ridges and cliff edges; secure loose gear.'),
('WIND_W','wind','gust_max_kmh','>=',60,'warning','Dangerous wind gusts','Do not hike exposed routes; pick a sheltered valley trail or postpone.'),
('HEAT_C','heat','temp_max_c','>=',30,'caution','High temperature','Carry at least 2 L of water and avoid the midday hours.'),
('COLD_C','cold','temp_min_c','<=',3,'caution','Near-freezing temperature','Wear layers, a hat and gloves; check for ice on shaded paths.'),
('DAY_C','daylight','daylight_margin_min','<',60,'caution','Finishing close to sunset','Bring a head torch and keep a steady pace.'),
('DAY_W','daylight','daylight_margin_min','<',30,'warning','Finishing after or near sunset','Start by {latest_start} or choose a shorter trail.');
