INSERT INTO activity (user_id, trail_id, plan_id, hiked_on, distance_km, duration_min, notes, created_at) VALUES
(3, 7, NULL, CURRENT_DATE - 9, 4.9, 135, 'Misty start but the view over Caniçada opened up at the top. Trail well marked; the descent is slippery on wet granite, so take your time.', now() - interval '9 days'),
(4, 5, NULL, CURRENT_DATE - 5, 8.7, 175, 'Went early to beat the crowds. The stairs at the Espiunca end are tough for beginners: start from Areinho if you can.', now() - interval '5 days'),
(2, 3, NULL, CURRENT_DATE - 3, 8.1, 162, 'Club hike with 9 people. Wind picked up on the ridge exactly as the check predicted, we used the lower path back.', now() - interval '3 days'),
(1, 2, 5, CURRENT_DATE - 6, 9.0, 150, 'Easy and flat. Very windy near the lighthouse, glad I brought a jacket.', now() - interval '1 day');
